package client

import (
	"context"
	"fmt"
	"net/http"
	"time"
)

// Config configures retry behavior.
type Config struct {
	MaxRetries  int
	InitialWait time.Duration
	BackoffMult float64 // multiplier per retry (e.g. 2.0 = exponential)
}

// DefaultConfig provides sensible defaults.
var DefaultConfig = Config{
	MaxRetries:  3,
	InitialWait: 100 * time.Millisecond,
	BackoffMult: 2.0,
}

// Client wraps http.Client with retry logic.
type Client struct {
	hc  *http.Client
	cfg Config
}

// New creates a retrying HTTP client.
func New(hc *http.Client, cfg Config) *Client {
	return &Client{hc: hc, cfg: cfg}
}

// Get performs a GET request with retry on 5xx or network error.
// Returns the last response (or error) after all retries are exhausted.
func (c *Client) Get(ctx context.Context, url string) (*http.Response, error) {
	// TODO: implement with retry
	return c.hc.Get(url)
}

