package client_test

import (
	"context"
	"net/http"
	"net/http/httptest"
	"sync/atomic"
	"testing"
	"time"

	"github.com/ai-verification/retry-client/client"
)

func TestGetSuccessFirstTry(t *testing.T) {
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(200)
	}))
	defer s.Close()
	c := client.New(s.Client(), client.Config{MaxRetries: 3, InitialWait: 0, BackoffMult: 1})
	resp, err := c.Get(context.Background(), s.URL)
	if err != nil || resp.StatusCode != 200 {
		t.Fatalf("expected 200 nil, got %v %v", resp, err)
	}
}

func TestRetryOn500(t *testing.T) {
	var calls atomic.Int32
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if calls.Add(1) < 3 {
			w.WriteHeader(500)
		} else {
			w.WriteHeader(200)
		}
	}))
	defer s.Close()
	c := client.New(s.Client(), client.Config{MaxRetries: 3, InitialWait: 0, BackoffMult: 1})
	resp, err := c.Get(context.Background(), s.URL)
	if err != nil || resp.StatusCode != 200 {
		t.Fatalf("expected 200, got %v %v", resp, err)
	}
	if calls.Load() != 3 {
		t.Fatalf("expected 3 calls, got %d", calls.Load())
	}
}

func TestExhaustedRetriesReturnsLastResponse(t *testing.T) {
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(503)
	}))
	defer s.Close()
	c := client.New(s.Client(), client.Config{MaxRetries: 2, InitialWait: 0, BackoffMult: 1})
	resp, _ := c.Get(context.Background(), s.URL)
	if resp == nil || resp.StatusCode != 503 {
		t.Fatalf("expected 503 response, got %v", resp)
	}
}

func TestContextCancellation(t *testing.T) {
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(500)
	}))
	defer s.Close()
	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()
	c := client.New(s.Client(), client.Config{MaxRetries: 10, InitialWait: 20 * time.Millisecond, BackoffMult: 1})
	_, err := c.Get(ctx, s.URL)
	if err == nil {
		t.Fatal("expected context cancellation error")
	}
}
